import {rnd} from '../core.js';import {particles,impacts} from '../state.js';export function lightningImpact(x,y){impacts.push({x,y,radius:8,life:420,electric:true});for(let i=0;i<24;i++){const angle=rnd(0,Math.PI*2),speed=rnd(2,8);particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:rnd(180,500),size:rnd(2,5),electric:true})}}
export function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt*1000;p.x+=p.vx;p.y+=p.vy;p.vy+=.025;if(p.life<=0)particles.splice(i,1)}}export function updateImpacts(dt){for(let i=impacts.length-1;i>=0;i--){const p=impacts[i];p.radius+=dt*180;p.life-=dt*1000;if(p.life<=0)impacts.splice(i,1)}}
